-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.card_quality_limits()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object('min_students', 5, 'min_calibrated', 10, 'fast_ms', 2000, 'hidden_share', 0.1,
                            'max_list', 200);
$function$;

grant execute on function public.card_quality_limits() to service_role;
